/** [ప్రశ్న, సరైన జవాబు, తప్పు జవాబులు, సూచన, వివరణ] */
type MQ = [string, string, string[], string, string];
const mcq = (key: string, hint0: string, bank: MQ[], d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const [q, a, w, h1, why] = r.pick(bank);
  return {
    type: 'mcq', prompt: q, ...choose(r, a, w), hints: [hint0, h1],
    mistakes: [{ when: 'wrong', explain: `సరికాదు. ${why}` }],
    solution: [`సరైన జవాబు: ${a}.`, why],
  };
}, d);

const matchT = (key: string, what: string, pool: [string, string][], hints: string[], n = 4, d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const pairs = r.shuffle(pool).slice(0, n);
  const m = matching(r, pairs);
  return {
    type: 'match', prompt: `${what}: ${pairs.map((x) => x[0]).join(' · ')}`, left: m.left, right: m.right, answer: m.answer,
    hints, mistakes: [{ when: 'wrong', explain: 'కనీసం ఒక జత తప్పుగా ఉంది. ఎడమవైపు ఒక్కొక్క అంశాన్ని తీసుకొని దానికి సరిపోయేదాన్ని విడిగా సరిచూడండి.' }],
    solution: pairs.map(([a, b]) => `${a} → ${b}`),
  };
}, d);

/** [ప్రశ్న, సరైన క్రమం, ఎందుకు] */
type OQ = [string, string[], string];
const orderT = (key: string, bank: OQ[], hints: string[], d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const [prompt, steps, why] = r.pick(bank);
  return {
    type: 'order', prompt, ...ordering(r, steps), hints,
    mistakes: [{ when: 'wrong', explain: `క్రమం ఇంకా సరిగా లేదు. ${why}` }],
    solution: [...steps.map((s, i) => `${i + 1}. ${s}`), why],
  };
}, d);

const tapT = (key: string, prompt: string, pool: [string, boolean][], hints: string[], why: string, n = 5, d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const pick = r.shuffle(pool).slice(0, n);
  const yes = pool.find((x) => x[1])!, no = pool.find((x) => !x[1])!;
  if (!pick.some((x) => x[1])) pick[0] = yes;
  if (!pick.some((x) => !x[1])) pick[n - 1] = no;
  return {
    type: 'tap', prompt, ...tapAll(r, pick.map(([label, ok]) => ({ label, ok }))), hints,
    mistakes: [{ when: 'wrong', explain: `ప్రతి ఎంపికను విడిగా పరీక్షించండి. ${why}` }],
    solution: [`సరైనవి: ${pick.filter((x) => x[1]).map((x) => x[0]).join(', ')}.`, why],
  };
}, d);

const obj = (id: string, title: string, intro: Block[], examples: ExSpec[], practice: TSpec[]): OSpec => ({ id, title, prereqs: [], intro, examples, practice });

