const SAMASA_NAMES = ['ద్వంద్వ సమాసం', 'షష్ఠీ తత్పురుష సమాసం', 'విశేషణ పూర్వపద కర్మధారయ సమాసం', 'ద్విగు సమాసం', 'బహువ్రీహి సమాసం', 'ఉపమాన పూర్వపద కర్మధారయ సమాసం', 'అవ్యయీభావ సమాసం', 'పంచమీ తత్పురుష సమాసం'];
const samasaMcq = (key: string, filter: (name: string) => boolean): TSpec => tp(key, (r) => {
  const pool = SAMASA_POOL.filter((x) => filter(x[2]));
  const [w, v, n] = r.pick(pool);
  const wrong = r.shuffle(SAMASA_NAMES.filter((x) => x !== n && !n.startsWith(x.split(' ')[0])));
  return {
    type: 'mcq', prompt: `"${w}" — విగ్రహ వాక్యం: "${v}". ఇది ఏ సమాసం?`, ...choose(r, n, wrong.slice(0, 3)),
    hints: ['విగ్రహ వాక్యంలోని కీలక పదాన్ని చూడండి: "యును" (ద్వంద్వ), "యొక్క/వలన/యందు" (తత్పురుష), "ఐన/వంటి/అనెడి" (కర్మధారయ), సంఖ్య (ద్విగు), "కలవాడు/కలది" (బహువ్రీహి).', 'బహువ్రీహిలో రెండు పదాలూ కాకుండా మూడో వ్యక్తి/వస్తువు అర్థమవుతుంది.'],
    mistakes: [{ when: 'wrong', explain: `సరికాదు. "${v}" అనే విగ్రహ వాక్యం ${n} లక్షణాన్ని చూపుతోంది.` }],
    solution: [`${w} = ${v}`, `కాబట్టి ఇది ${n}.`],
  };
});
const samasaVigraha = (key: string, filter: (name: string) => boolean): TSpec => tp(key, (r) => {
  const pool = SAMASA_POOL.filter((x) => filter(x[2]));
  const pick = r.shuffle(pool).slice(0, 4);
  const m = matching(r, pick.map(([w, v]) => [w, v] as [string, string]));
  return {
    type: 'match', prompt: `సమాస పదాలకు సరైన విగ్రహ వాక్యాలను జతపరచండి: ${pick.map((x) => x[0]).join(' · ')}`, left: m.left, right: m.right, answer: m.answer,
    hints: ['ప్రతి సమాస పదాన్ని రెండు భాగాలుగా విడదీసి, వాటి మధ్య ఉన్న సంబంధాన్ని మాటల్లో చెప్పండి.', 'విగ్రహ వాక్యంలో సమాసంలోని రెండు పదాలూ (లేదా వాటి రూపాలు) కనిపిస్తాయి.'],
    mistakes: [{ when: 'wrong', explain: 'ఒక జత సరిపోలలేదు. విగ్రహ వాక్యంలో సమాస పదంలోని రెండు భాగాలూ ఉన్నాయో లేదో చూడండి.' }],
    solution: pick.map(([w, v, n]) => `${w} = ${v} (${n})`),
  };
});

